scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById(id).innerText == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 마우스를 위와 아래에 있는 inputbox 각각에 over한다.
    //1. After running the main sample, overlay the mouse on each of the inputbox above and below it.
    //Verify step 1. w1_input1dummy, w2_input1dummy The tooltip value is displayed.
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('w1_input1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_2_balloonTip_label', $p.id+'w1_input1dummy')", "true");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('w2_input1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'wq_uuid_2_balloonTip_label', $p.id+'w2_input1dummy')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
